$ErrorActionPreference = 'Stop'
Write-Host 'ADVİSE DIGITAL TAMIR BAŞLIYOR...' -ForegroundColor Cyan

$target = Split-Path -Parent $MyInvocation.MyCommand.Path
$mobile = Join-Path $target 'mobile'
$backend = Join-Path $target 'backend'
if (-not (Test-Path $mobile)) { throw "mobile klasörü bulunamadı: $mobile" }
if (-not (Test-Path $backend)) { throw "backend klasörü bulunamadı: $backend" }
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backup = Join-Path $target ("backup-before-advise-now-" + $stamp)
New-Item -ItemType Directory -Force -Path $backup | Out-Null
Write-Host ("Yedek oluşturuluyor: " + $backup) -ForegroundColor Yellow
if (Test-Path (Join-Path $mobile 'lib')) { Copy-Item (Join-Path $mobile 'lib') (Join-Path $backup 'lib') -Recurse -Force }
if (Test-Path (Join-Path $mobile 'pubspec.yaml')) { Copy-Item (Join-Path $mobile 'pubspec.yaml') (Join-Path $backup 'pubspec.yaml') -Force }
if (Test-Path (Join-Path $backend 'package.json')) { Copy-Item (Join-Path $backend 'package.json') (Join-Path $backup 'package.json') -Force }
$payload = @{

  'mobile/lib/main.dart' = @'

'@

