'@

  'mobile/pubspec.yaml' = @'

'@

  'backend/package.json' = @'

'@

 }
function Write-PayloadFile($relative, $b64) {
  $path = Join-Path $target $relative
  $dir = Split-Path -Parent $path
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String(($b64 -replace '\s','')))
}
# Remove stale Dart test/patch files that previously generated the bulk of analyzer errors.
$stale = @(
  'mobile/lib/admin_test_ticket_delete_patch.dart',
  'mobile/lib/admin_test_ticket_delete_patch.g.dart'
)
foreach ($rel in $stale) {
  $p = Join-Path $target $rel
  if (Test-Path $p) { Remove-Item $p -Force; Write-Host ("Silindi: " + $rel) -ForegroundColor DarkYellow }
}
# Replace ONLY the app source layer and backend manifest.
if (Test-Path (Join-Path $mobile 'lib')) { Remove-Item (Join-Path $mobile 'lib') -Recurse -Force }
foreach ($item in $payload.GetEnumerator()) {
  Write-PayloadFile $item.Key $item.Value
}
Write-Host ''
Write-Host 'REPAIR TAMAMLANDI.' -ForegroundColor Green
Write-Host ("Yedek: " + $backup) -ForegroundColor DarkGray
Write-Host ''
Write-Host 'Şimdi sırayla çalıştır:' -ForegroundColor Cyan
Write-Host '  cd C:\Users\ANL\Desktop\meta\backend'
